/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic [7:0] code,
    output logic [3:0] out,
    output logic       valid
);
    always_comb begin
        out = 4'd0;
        valid = 1'b1;
        case (code)
            8'h45: out = 4'd0;
            8'h16: out = 4'd1;
            8'h1e: out = 4'd2;
            8'h26: out = 4'd3;
            8'h25: out = 4'd4;
            8'h2e: out = 4'd5;
            8'h36: out = 4'd6;
            8'h3d: out = 4'd7;
            8'h3e: out = 4'd8;
            8'h46: out = 4'd9;
            default: begin
                out = 4'd0;
                valid = 1'b0;
            end
        endcase
    end
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic [7:0] code;
    wire [3:0] out;
    wire valid;
    logic [7:0] scancodes [0:9];
    integer checks = 0;
    TopModule dut (.code(code), .out(out), .valid(valid));

    task automatic check_code(input integer value);
        logic [3:0] expected_out;
        logic expected_valid;
        begin
            expected_out = 4'"'d0;
            expected_valid = 1'b0;
            for (integer digit = 0; digit < 10; digit = digit + 1) begin
                if (value == scancodes[digit]) begin
                    expected_out = digit;
                    expected_valid = 1'b1;
                end
            end
            code = value;
            #1;
            if (out "'!== expected_out || valid !== expected_valid)
                $fatal(1, "FAIL code=%h out=%h valid=%b expected=%h,%b",
                       code, out, valid, expected_out, expected_valid);
            checks = checks + 1;
        end
    endtask

    initial begin
        scancodes[0] = 8'"'h45;
        scancodes[1] = 8'h16;
        scancodes[2] = 8'h1e;
        scancodes[3] = 8'h26;
        scancodes[4] = 8'h25;
        scancodes[5] = 8'h2e;
        scancodes[6] = 8'h36;
        scancodes[7] = 8'h3d;
        scancodes[8] = 8'h3e;
        scancodes[9] = 8'h46;
        for (integer value = 0; value < 256; value = value + 1)
            check_code(value);
        for (integer value = 255; value >= 0; value = value - 1)
            check_code(value);
        "'$display("PASS: %0d checks covering all 256 binary codes twice", checks);
        $finish;
    end
    initial begin
        #1000;
        $fatal(1, "FAIL: testbench timeout");
    end
endmodule
EOF
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > development_compile.log 2>&1
compile_rc=$?
cat development_compile.log
if [ "$compile_rc" -ne 0 ]; then exit "$compile_rc"; fi
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > development_simulation.log 2>&1
simulation_rc=$?
cat development_simulation.log
exit "$simulation_rc"'

